BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL search_path=public,pg_catalog;
LOCK TABLE public.users IN SHARE ROW EXCLUSIVE MODE;
DO $guard$
DECLARE t record; row_count bigint;
BEGIN
 IF current_setting('server_version_num')::integer / 10000 <> 17 THEN RAISE EXCEPTION 'requires PostgreSQL 17'; END IF;
 IF current_user <> 'postgres' OR current_database() <> 'postgres' THEN RAISE EXCEPTION 'unexpected staging database role'; END IF;
 IF to_regclass('public.task_data') IS NULL OR to_regclass('public.batch_tasks') IS NULL OR to_regclass('public.watermark_removal_tasks') IS NULL OR to_regclass('public.flux_data') IS NOT NULL THEN RAISE EXCEPTION 'reconciled staging baseline required'; END IF;
 FOR t IN SELECT c.oid::regclass AS relation FROM pg_class c JOIN pg_namespace ns ON ns.oid=c.relnamespace WHERE ns.nspname='public' AND c.relkind IN ('r','p') LOOP
  EXECUTE format('SELECT count(*) FROM %s',t.relation) INTO row_count;
  IF row_count<>0 THEN RAISE EXCEPTION 'staging public data is not empty'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM auth.users)<>0 OR (SELECT count(*) FROM storage.objects)<>0 THEN RAISE EXCEPTION 'staging auth/storage is not empty'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conrelid='public.users'::regclass AND c.contype='p' AND pg_get_constraintdef(c.oid)='PRIMARY KEY (id)') THEN RAISE EXCEPTION 'users PK mismatch'; END IF;
 IF (SELECT count(*) FROM pg_roles WHERE rolname IN ('postgres','anon','authenticated'))<>3 THEN RAISE EXCEPTION 'expected role is missing'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['processing_queue','processing_queue_id_seq','processing_queue_pkey','processing_queue_status_scheduled_at_idx','background_images','background_images_id_seq','background_images_pkey','background_images_type_idx','background_images_category_idx','background_images_is_public_idx','background_images_is_default_idx','background_images_sort_order_idx','background_compositions','background_compositions_id_seq','background_compositions_pkey','background_compositions_user_id_idx','background_compositions_status_idx','background_compositions_created_at_idx']) AS object_name WHERE to_regclass('public.'||object_name) IS NOT NULL) THEN RAISE EXCEPTION 'new baseline object already exists'; END IF;
 IF EXISTS(SELECT 1 FROM pg_constraint WHERE connamespace='public'::regnamespace AND conname IN ('processing_queue_pkey','background_images_pkey','background_compositions_pkey','background_compositions_user_id_fkey','background_compositions_background_image_id_fkey')) THEN RAISE EXCEPTION 'new baseline constraint already exists'; END IF;
END $guard$;
CREATE TABLE public.processing_queue (
  id SERIAL PRIMARY KEY,
  task_type TEXT NOT NULL,
  payload JSONB NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  retry_count INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  scheduled_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP(3) NOT NULL
);
CREATE INDEX processing_queue_status_scheduled_at_idx
  ON public.processing_queue (status, scheduled_at);

CREATE TABLE public.background_images (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  type TEXT NOT NULL,
  category TEXT,
  image_url TEXT NOT NULL,
  thumbnail_url TEXT,
  file_size INTEGER,
  width INTEGER,
  height INTEGER,
  color TEXT,
  gradient JSONB,
  tags TEXT[],
  is_public BOOLEAN NOT NULL DEFAULT true,
  is_default BOOLEAN NOT NULL DEFAULT false,
  sort_order INTEGER NOT NULL DEFAULT 0,
  usage_count INTEGER NOT NULL DEFAULT 0,
  download_count INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP(3) NOT NULL
);
CREATE INDEX background_images_type_idx ON public.background_images (type);
CREATE INDEX background_images_category_idx ON public.background_images (category);
CREATE INDEX background_images_is_public_idx ON public.background_images (is_public);
CREATE INDEX background_images_is_default_idx ON public.background_images (is_default);
CREATE INDEX background_images_sort_order_idx ON public.background_images (sort_order);

CREATE TABLE public.background_compositions (
  id SERIAL PRIMARY KEY,
  user_id TEXT,
  foreground_image_url TEXT NOT NULL,
  background_image_id INTEGER,
  background_type TEXT NOT NULL,
  background_data JSONB NOT NULL,
  composition_params JSONB NOT NULL,
  result_image_url TEXT,
  result_image_size INTEGER,
  status TEXT NOT NULL DEFAULT 'pending',
  error_message TEXT,
  download_count INTEGER NOT NULL DEFAULT 0,
  view_count INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP(3) NOT NULL,
  completed_at TIMESTAMP(3),
  CONSTRAINT background_compositions_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES public.users(id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT background_compositions_background_image_id_fkey
    FOREIGN KEY (background_image_id) REFERENCES public.background_images(id)
    ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX background_compositions_user_id_idx
  ON public.background_compositions (user_id);
CREATE INDEX background_compositions_status_idx
  ON public.background_compositions (status);
CREATE INDEX background_compositions_created_at_idx
  ON public.background_compositions (created_at);

-- Server-only access, consistent with the existing staging baseline boundary.
-- Verify the server role can use these objects before applying this policy.
ALTER TABLE public.processing_queue ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.background_images ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.background_compositions ENABLE ROW LEVEL SECURITY;
