  IF seq IS DISTINCT FROM 'public.'||t||'_id_seq' THEN RAISE EXCEPTION 'serial sequence mismatch'; END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_depend d JOIN pg_attribute a ON a.attrelid=d.refobjid AND a.attnum=d.refobjsubid WHERE d.classid='pg_class'::regclass AND d.objid=seq::regclass AND d.refobjid=('public.'||t)::regclass AND d.deptype='a' AND a.attname='id') THEN RAISE EXCEPTION 'sequence ownership mismatch'; END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=('public.'||t)::regclass AND relrowsecurity AND NOT relforcerowsecurity AND pg_get_userbyid(relowner)='postgres') OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=('public.'||t)::regclass) THEN RAISE EXCEPTION 'server-only RLS mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 'S'::"char" ELSE 'r'::"char" END,c.relowner))) acl WHERE c.oid IN (('public.'||t)::regclass,seq::regclass) AND (acl.grantee=0 OR acl.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated')))) THEN RAISE EXCEPTION 'public table/sequence ACL remains'; END IF;
  IF has_table_privilege('anon',('public.'||t)::regclass,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege('authenticated',('public.'||t)::regclass,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_sequence_privilege('anon',seq::regclass,'SELECT,USAGE,UPDATE') OR has_sequence_privilege('authenticated',seq::regclass,'SELECT,USAGE,UPDATE') THEN RAISE EXCEPTION 'inherited public access remains'; END IF;
 END LOOP;
END $verify$;
SELECT jsonb_build_object(
 'server_version',current_setting('server_version'),'current_user',current_user,'database',current_database(),
 'counts',jsonb_build_object('processing_queue',(SELECT count(*) FROM public.processing_queue),'background_images',(SELECT count(*) FROM public.background_images),'background_compositions',(SELECT count(*) FROM public.background_compositions),'users',(SELECT count(*) FROM public.users),'auth_users',(SELECT count(*) FROM auth.users),'storage_objects',(SELECT count(*) FROM storage.objects)),
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'ordinal',ordinal_position,'type',data_type,'nullable',is_nullable,'default',column_default,'precision',datetime_precision) ORDER BY table_name,ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('processing_queue','background_images','background_compositions')),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',tab.relname,'name',idx.relname,'primary',i.indisprimary,'unique',i.indisunique,'valid',i.indisvalid,'ready',i.indisready,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY idx.relname) FROM pg_index i JOIN pg_class idx ON idx.oid=i.indexrelid JOIN pg_class tab ON tab.oid=i.indrelid WHERE i.indrelid IN ('public.processing_queue'::regclass,'public.background_images'::regclass,'public.background_compositions'::regclass)),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'type',contype,'definition',pg_get_constraintdef(oid),'validated',convalidated) ORDER BY conname) FROM pg_constraint WHERE conrelid IN ('public.processing_queue'::regclass,'public.background_images'::regclass,'public.background_compositions'::regclass)),
 'relations',(SELECT jsonb_agg(jsonb_build_object('table',relname,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',relacl) ORDER BY relname) FROM pg_class WHERE oid IN ('public.processing_queue'::regclass,'public.background_images'::regclass,'public.background_compositions'::regclass)),
 'sequences',jsonb_build_array(
 (SELECT jsonb_build_object('name','processing_queue_id_seq','last_value',last_value,'is_called',is_called,'owned_sequence',pg_get_serial_sequence('public.processing_queue','id')) FROM public.processing_queue_id_seq),
 (SELECT jsonb_build_object('name','background_images_id_seq','last_value',last_value,'is_called',is_called,'owned_sequence',pg_get_serial_sequence('public.background_images','id')) FROM public.background_images_id_seq),
 (SELECT jsonb_build_object('name','background_compositions_id_seq','last_value',last_value,'is_called',is_called,'owned_sequence',pg_get_serial_sequence('public.background_compositions','id')) FROM public.background_compositions_id_seq))
) AS result;

DO $postcheck$
DECLARE t record; row_count bigint; table_count integer:=0;
BEGIN
 IF current_setting('server_version_num')::integer / 10000<>17 OR current_user<>'postgres' OR current_database()<>'postgres' THEN RAISE EXCEPTION 'staging identity/version mismatch'; END IF;
 FOR t IN SELECT c.oid::regclass AS relation FROM pg_class c JOIN pg_namespace ns ON ns.oid=c.relnamespace WHERE ns.nspname='public' AND c.relkind IN ('r','p') LOOP
  EXECUTE format('SELECT count(*) FROM %s',t.relation) INTO row_count; table_count:=table_count+1;
  IF row_count<>0 THEN RAISE EXCEPTION 'staging public data remains after rollback'; END IF;
 END LOOP;
 IF table_count<>186 OR (SELECT count(*) FROM auth.users)<>0 OR (SELECT count(*) FROM storage.objects)<>0 THEN RAISE EXCEPTION 'staging postrollback count mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='background_images' AND column_name='tags' AND udt_schema='pg_catalog' AND udt_name='_text') THEN RAISE EXCEPTION 'tags text array mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.column_privileges WHERE table_schema='public' AND table_name IN ('processing_queue','background_images','background_compositions') AND grantee IN ('PUBLIC','anon','authenticated')) THEN RAISE EXCEPTION 'client column ACL remains'; END IF;
END $postcheck$;
SELECT jsonb_build_object('phase','final_postcheck_passed','public_tables',186,'nonempty_public_tables',0,'auth_users',(SELECT count(*) FROM auth.users),'storage_objects',(SELECT count(*) FROM storage.objects),'tags_type','text[]','client_column_grants',0) AS result;
